  Future<void> _exportToJson() async {
    setState(() {
      _isLoading = true;
      _status = 'Creating and exporting template...';
    });

    try {
      final json = buildExportTemplateJson();

      setState(() {
        _status = 'Template exported to JSON:\n\n$json';
      });
    } catch (e) {
