  Future<void> _runManagedPdfAction({
    required String actionId,
    required String fileName,
    required String startingStatus,
    required String successStatus,
  }) async {
    if (_isLoading) return;

    setState(() {
      _isLoading = true;
      _status = startingStatus;
    });

    try {
      final result = await generateExamplePdf(
        builder: ExampleBackgroundPdfBuilder(
          config: geniusPdfConfig,
          backgroundGenerator: () =>
              generateTemplateEngineActionInBackground(actionId: actionId),
        ),
        fileName: fileName,
        metadata: <String, dynamic>{
          'feature': 'template_engine',
          'screen': 'TemplateEngineSingleExampleHost',
          'actionId': actionId,
          'workflow': 'template-engine-action',
          'showGenerationToast': true,
        },
      );

      if (!mounted) return;
      setState(() => _status = successStatus);

      final path = result.filePath;
      if (path != null && path.isNotEmpty) {
        await demoDocuments.open(path);
      }
    } catch (error) {
      if (mounted) {
        setState(() => _status = 'Error: $error');
      }
    } finally {
      if (mounted) setState(() => _isLoading = false);
    }
  }
